// @target tiktok.com
/**
 * tk-05-upload-feed.js
 *
 * Injects alpha_paws_black_cat_phone.mp4 into TikTok Studio upload input
 * and inspects the resulting editor form.
 */

try {
  if (!window.location.href.includes('/tiktokstudio/upload')) {
    return { ok: false, error: 'Not on upload page: ' + window.location.href }
  }

  const fileInput = document.querySelector('input[type="file"]')
  if (!fileInput) {
    return { ok: false, error: 'No input[type="file"] found' }
  }

  // Convert base64 to Blob & File
  const b64 = ""
  const bin = atob(b64)
  const len = bin.length
  const bytes = new Uint8Array(len)
  for (let i = 0; i < len; i++) {
    bytes[i] = bin.charCodeAt(i)
  }
  const blob = new Blob([bytes], { type: 'video/mp4' })
  const file = new File([blob], 'alpha_paws_black_cat_phone.mp4', { type: 'video/mp4', lastModified: Date.now() })

  // Use DataTransfer to populate input.files
  const dt = new DataTransfer()
  dt.items.add(file)
  fileInput.files = dt.files

  // Dispatch change and input events
  fileInput.dispatchEvent(new Event('change', { bubbles: true }))
  fileInput.dispatchEvent(new Event('input', { bubbles: true }))

  // Check state immediately after dispatch
  return {
    ok: true,
    fileAssigned: true,
    fileName: file.name,
    fileSize: file.size,
    inputFilesCount: fileInput.files.length,
    note: 'File dispatched to input. Wait for TikTok Studio to process and render metadata editor.'
  }
} catch (err) {
  return { ok: false, error: err.message, stack: err.stack }
}
